<tr data-order-line><td><select name="lines[<?= $lineKey ?>][product_id]" aria-label="Producto" data-order-product><option value="">Selecciona un producto</option><?php foreach ($page['catalogs']['products'] as $product): ?><option value="<?= (int) $product['id'] ?>" data-price="<?= salesEscape($product['price']) ?>" data-currency="<?= salesEscape($product['currency_code']) ?>" data-tax="<?= (int) ($product['tax_id'] ?? 0) ?>" <?= (int) ($line['product_id'] ?? 0) === (int) $product['id'] ? 'selected' : '' ?>><?= salesEscape($product['name']) ?></option><?php endforeach; ?></select></td>
    <td><input name="lines[<?= $lineKey ?>][quantity]" aria-label="Cantidad" inputmode="decimal" maxlength="12" data-order-quantity value="<?= salesEscape(decimalInput($line['quantity'] ?? '1.00')) ?>"></td>
    <td><input name="lines[<?= $lineKey ?>][unit_price]" aria-label="Precio unitario" inputmode="decimal" maxlength="13" data-order-price value="<?= salesEscape($line['unit_price'] ?? '0.00') ?>"></td>
    <td><select name="lines[<?= $lineKey ?>][tax_id]" aria-label="Impuesto" data-order-tax><option value="">Sin impuesto</option><?php foreach ($page['catalogs']['taxes'] as $tax): ?><option value="<?= (int) $tax['id'] ?>" data-rate="<?= salesEscape((int)($line['tax_id']??0)===(int)$tax['id'] && isset($line['tax_rate']) ? $line['tax_rate'] : $tax['rate']) ?>" <?= (int) ($line['tax_id'] ?? 0) === (int) $tax['id'] ? 'selected' : '' ?>><?= salesEscape($tax['name']) ?></option><?php endforeach; ?></select></td>
    <td data-order-line-base><?= salesEscape($line['base_amount'] ?? '0.00') ?></td><td data-order-line-total><?= salesEscape($line['total_amount'] ?? '0.00') ?></td>
    <?php if (! $locked): ?><td class="contact-row-action"><button type="button" class="contact-button contact-icon-button" data-order-remove hidden aria-label="Quitar producto" title="Quitar producto"><?php require dirname(__DIR__) . '/partials/remove-icon.php'; ?></button></td><?php endif; ?>
</tr>
